import{_ as t,o as n,c as i,a3 as r}from"./chunks/framework.z_KJ15Ep.js";const d="/bilder/reportdesigner/tutorials-reporting-schriftart-einbetten.png",g=JSON.parse('{"title":"Schriftarten und Sonderzeichen in PDF-Ausgaben","description":"","frontmatter":{"title":"Schriftarten und Sonderzeichen in PDF-Ausgaben","source_pageid":1427,"source_revision":6572},"headers":[],"relativePath":"reporting/reportdesigner/probleme-mit-fehlenden-schriftarten-im-pdf-dokument-tutorial.md","filePath":"reporting/reportdesigner/probleme-mit-fehlenden-schriftarten-im-pdf-dokument-tutorial.md"}'),a={name:"reporting/reportdesigner/probleme-mit-fehlenden-schriftarten-im-pdf-dokument-tutorial.md"};function s(l,e,o,u,h,c){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="schriftarten-und-sonderzeichen-in-pdf-ausgaben" tabindex="-1">Schriftarten und Sonderzeichen in PDF-Ausgaben <a class="header-anchor" href="#schriftarten-und-sonderzeichen-in-pdf-ausgaben" aria-label="Permalink to &quot;Schriftarten und Sonderzeichen in PDF-Ausgaben&quot;">​</a></h1><p>Konfigurieren Sie die PDF-Ausgabe so, dass Sonderzeichen erhalten bleiben und Schriftarten eingebettet werden. Die Einstellungstabelle zeigt die Auswirkungen auf Darstellung und Dateigröße.</p><h2 id="pdf-einstellungen-prufen" tabindex="-1">PDF-Einstellungen prüfen <a class="header-anchor" href="#pdf-einstellungen-prufen" aria-label="Permalink to &quot;PDF-Einstellungen prüfen&quot;">​</a></h2><p><a href="/bilder/reportdesigner/tutorials-reporting-schriftart-einbetten.png"><img src="'+d+'" alt="Einstellungen pdf-Settings." loading="lazy"></a></p><p><em>Einstellungen pdf-Settings.</em></p><p>Eine fehlerhafte PDF-Darstellung kann durch die Zeichencodierung oder durch fehlende Schriftarten auf dem Anzeigesystem entstehen.</p><ol><li>Öffnen Sie <strong>PDFSettings</strong> und setzen Sie <code>FontEncoding = feUnicode</code>. Damit bleiben auch Sonderzeichen wie <code>ĉ</code> erhalten, die beispielsweise in Namen vorkommen können.</li><li>Verwenden Sie <code>EmbedFontOptions = efUseSubset</code>, um nur die tatsächlich benötigten Zeichen einzubetten.</li><li>Erzeugen Sie die PDF-Ausgabe erneut und kontrollieren Sie Schrift und Sonderzeichen.</li></ol><p>Mit <code>feUnicode</code> wird zugleich das Einbetten der Schriftarten aktiviert. Dadurch kann die PDF-Datei auch auf einem System mit der vorgesehenen Schrift dargestellt werden, auf dem diese Schrift nicht installiert ist. Die Beschränkung auf verwendete Zeichen verringert die Dateigröße.</p><h2 id="auswirkungen-der-einstellungen" tabindex="-1">Auswirkungen der Einstellungen <a class="header-anchor" href="#auswirkungen-der-einstellungen" aria-label="Permalink to &quot;Auswirkungen der Einstellungen&quot;">​</a></h2><p>Die folgende Tabelle enthält die beschriebenen Kombinationen und ihre Auswirkungen:</p><table tabindex="0"><thead><tr><th>Einstellung FontEncoding</th><th>Einstellung EmbedFontOptions</th><th>Auswirkung Sonderzeichen</th><th>Auswirkung Einbettung</th><th>Auswirkung Dateigröße</th></tr></thead><tbody><tr><td>feAnsi</td><td>[]</td><td>nein</td><td>nein</td><td>klein</td></tr><tr><td>feAnsi</td><td>[efAllFonts]</td><td>nein</td><td>ja</td><td>groß</td></tr><tr><td>feAnsi</td><td>[efAllFonts, efUseSubset]</td><td>nein</td><td>ja</td><td>mittel</td></tr><tr><td>feAnsi</td><td>[efUseSubset]</td><td>nein</td><td>nein</td><td>klein</td></tr><tr><td>feUnicode</td><td>[]</td><td>ja</td><td>ja</td><td>groß</td></tr><tr><td>feUnicode</td><td>[efAllFonts]</td><td>ja</td><td>ja</td><td>groß</td></tr><tr><td>feUnicode</td><td>[efAllFonts, efUseSubset]</td><td>ja</td><td>ja</td><td>mittel</td></tr><tr><td>feUnicode</td><td>[efUseSubset]</td><td>ja</td><td>ja</td><td>mittel</td></tr></tbody></table><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Probleme_mit_fehlenden_Schriftarten_im_pdf-Dokument_(Tutorial)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6572.</p>',13)])])}const p=t(a,[["render",s]]);export{g as __pageData,p as default};
